-- Preserve the historical Arrow dataset item and keep the Hity product on its own slug/SKUs.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM products WHERE slug='dam-midi-linen' AND name <> 'Arrow Woman Solid Cream Dress') THEN
        RAISE EXCEPTION 'Refusing to seed Arrow: slug dam-midi-linen belongs to a different product';
    END IF;
    IF EXISTS (SELECT 1 FROM products WHERE slug='dam-midi-linen-hity' AND name <> 'Đầm linen cổ tim dáng midi Hity') THEN
        RAISE EXCEPTION 'Refusing to seed Hity: slug dam-midi-linen-hity belongs to a different product';
    END IF;
    IF EXISTS (SELECT 1 FROM product_variants WHERE sku IN ('DML-001-SND-S','DML-001-SND-M') AND product_id <> (SELECT id FROM products WHERE slug='dam-midi-linen' AND name='Arrow Woman Solid Cream Dress')) THEN
        RAISE EXCEPTION 'Refusing to seed Arrow: historical SKU is owned by another product';
    END IF;
    IF EXISTS (SELECT 1 FROM product_variants WHERE sku IN ('HITY-DML-001-SND-S','HITY-DML-001-SND-M') AND product_id <> (SELECT id FROM products WHERE slug='dam-midi-linen-hity' AND name='Đầm linen cổ tim dáng midi Hity')) THEN
        RAISE EXCEPTION 'Refusing to seed Hity: Hity SKU is owned by another product';
    END IF;
END $$;

INSERT INTO products (brand_id, category_id, name, slug, short_description, description, base_price, sale_price, material, fit, gender, status, is_featured, is_new)
SELECT b.id,c.id,'Arrow Woman Solid Cream Dress','dam-midi-linen',U&'\0110\1EA7m n\1EEF m\00E0u kem t\1EEB dataset.',U&'T\00EAn v\00E0 \1EA3nh l\1EA5y t\1EEB c\00F9ng b\1EA3n ghi dataset. Gi\00E1 v\00E0 t\1ED3n kho l\00E0 d\1EEF li\1EC7u demo, kh\00F4ng ph\1EA3i gi\00E1 g\1ED1c t\1EEB ngu\1ED3n.',532000,469000,NULL,NULL,'FEMALE','ACTIVE',TRUE,TRUE
FROM brands b CROSS JOIN categories c WHERE b.slug='dataset-sample-myntra' AND c.slug='dam'
  AND NOT EXISTS (SELECT 1 FROM products existing WHERE existing.slug='dam-midi-linen' AND (existing.name <> 'Arrow Woman Solid Cream Dress' OR existing.brand_id <> b.id))
ON CONFLICT (slug) DO UPDATE SET brand_id=EXCLUDED.brand_id,category_id=EXCLUDED.category_id,name=EXCLUDED.name,
    short_description=EXCLUDED.short_description,description=EXCLUDED.description,base_price=EXCLUDED.base_price,
    sale_price=EXCLUDED.sale_price,gender=EXCLUDED.gender,status=EXCLUDED.status,is_featured=EXCLUDED.is_featured,
    is_new=EXCLUDED.is_new,updated_at=NOW()
WHERE products.name='Arrow Woman Solid Cream Dress' AND products.brand_id=EXCLUDED.brand_id;

INSERT INTO products (brand_id, category_id, name, slug, short_description, description, base_price, sale_price, material, fit, gender, status, is_featured, is_new)
SELECT b.id,c.id,U&'\0110\1EA7m linen c\1ED5 tim d\00E1ng midi Hity','dam-midi-linen-hity','Hity midi linen dress in sand tone.','Hity linen cotton midi dress with V neckline and A-line fit. Demo price and inventory.',532000,469000,'Linen cotton','A-line','FEMALE','ACTIVE',TRUE,TRUE
FROM brands b CROSS JOIN categories c WHERE b.slug='hity' AND c.slug='dam'
  AND NOT EXISTS (SELECT 1 FROM products existing WHERE existing.slug='dam-midi-linen-hity' AND (existing.name <> U&'\0110\1EA7m linen c\1ED5 tim d\00E1ng midi Hity' OR existing.brand_id <> b.id))
ON CONFLICT (slug) DO UPDATE SET brand_id=EXCLUDED.brand_id,category_id=EXCLUDED.category_id,name=EXCLUDED.name,
    short_description=EXCLUDED.short_description,description=EXCLUDED.description,base_price=EXCLUDED.base_price,
    sale_price=EXCLUDED.sale_price,material=EXCLUDED.material,fit=EXCLUDED.fit,gender=EXCLUDED.gender,
    status=EXCLUDED.status,is_featured=EXCLUDED.is_featured,is_new=EXCLUDED.is_new,updated_at=NOW()
WHERE products.name=U&'\0110\1EA7m linen c\1ED5 tim d\00E1ng midi Hity' AND products.brand_id=EXCLUDED.brand_id;

