DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.sku IN ('DML-001-SND-S','DML-001-SND-M') AND p.slug <> 'dam-midi-linen') THEN
        RAISE EXCEPTION 'Arrow SKU is already owned by a different product; seed aborted';
    END IF;
    IF EXISTS (SELECT 1 FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.sku IN ('HITY-DML-001-SND-S','HITY-DML-001-SND-M') AND p.slug <> 'dam-midi-linen-hity') THEN
        RAISE EXCEPTION 'Hity SKU is already owned by a different product; seed aborted';
    END IF;
END $$;

