    ('ao-khoac-bomber', 'AKB-001-BLK-M', '/assets/products/seed-catalog/jackets-black-nike-men-solid-black-jacket-15322.jpg', 'Nike Men Solid Black Jacket - Jackets (Black)', TRUE, 1),
