INSERT INTO user_addresses (user_id, recipient_name, phone, address_line1, city, district, ward, postal_code, is_default)
SELECT u.id, a.recipient_name, a.phone, a.address_line1, a.city, a.district, a.ward, a.postal_code, TRUE
FROM demo_addresses a JOIN users u ON u.email = a.email
WHERE NOT EXISTS (
    SELECT 1 FROM user_addresses existing
    WHERE existing.user_id = u.id AND existing.address_line1 = a.address_line1
      AND existing.city = a.city AND existing.district = a.district
);

