INSERT INTO orders (user_id, total_amount, vat_amount, shipping_fee, discount_amount, final_amount, shipping_address, payment_method, payment_status, order_status)
SELECT u.id, 840000, 67200, 30000, 0, 937200, '12 Le Loi, Hoan Kiem, Ha Noi', 'COD', 'PENDING', 'PENDING'
FROM users u
WHERE u.email = 'customer1@example.com'
  AND NOT EXISTS (
      SELECT 1 FROM orders existing
      WHERE existing.user_id = u.id AND existing.total_amount = 840000
        AND existing.vat_amount = 67200 AND existing.shipping_fee = 30000
        AND existing.final_amount = 937200 AND existing.payment_method = 'COD'
        AND existing.shipping_address = '12 Le Loi, Hoan Kiem, Ha Noi'
  );

INSERT INTO order_items (order_id, product_id, variant_id, sku, product_name, color, size, quantity, price, vat_amount)
SELECT o.id, p.id, v.id, v.sku, p.name, v.color, v.size, 1, item.price, item.vat_amount
FROM (VALUES
    ('ao-thun-basic', 'ATB-001-BLK-S', 280000::double precision, 22400::double precision),
    ('quan-jean-relaxed', 'QJR-001-BLU-30', 560000::double precision, 44800::double precision)
) AS item(product_slug, sku, price, vat_amount)
JOIN products p ON p.slug = item.product_slug
JOIN product_variants v ON v.sku = item.sku AND v.product_id = p.id
JOIN users u ON u.email = 'customer1@example.com'
JOIN orders o ON o.user_id = u.id AND o.total_amount = 840000 AND o.vat_amount = 67200
    AND o.shipping_fee = 30000 AND o.final_amount = 937200 AND o.payment_method = 'COD'
    AND o.shipping_address = '12 Le Loi, Hoan Kiem, Ha Noi'
WHERE NOT EXISTS (
    SELECT 1 FROM order_items existing WHERE existing.order_id = o.id AND existing.variant_id = v.id
);

-- Refresh only the deterministic demo order snapshots so they match the seeded catalog names.
UPDATE order_items oi
SET product_name=p.name,color=v.color,size=v.size
FROM products p
JOIN product_variants v ON v.product_id=p.id
JOIN orders o ON TRUE
JOIN users u ON u.id=o.user_id
WHERE oi.order_id=o.id AND oi.product_id=p.id AND oi.variant_id=v.id
  AND p.slug IN ('ao-thun-basic','quan-jean-relaxed')
  AND u.email='customer1@example.com' AND o.total_amount=840000
  AND o.vat_amount=67200 AND o.shipping_fee=30000 AND o.final_amount=937200
  AND o.payment_method='COD' AND o.shipping_address='12 Le Loi, Hoan Kiem, Ha Noi';

INSERT INTO payments (order_id, payment_method, provider, payment_ref, amount, status)
SELECT o.id, 'COD', 'Cash On Delivery', 'COD-ORD-DEMO-2026001', 937200, 'PENDING'
FROM orders o JOIN users u ON u.id = o.user_id
WHERE u.email = 'customer1@example.com' AND o.total_amount = 840000 AND o.vat_amount = 67200
  AND o.shipping_fee = 30000 AND o.final_amount = 937200 AND o.payment_method = 'COD'
  AND o.shipping_address = '12 Le Loi, Hoan Kiem, Ha Noi'
ON CONFLICT (order_id) DO NOTHING;

INSERT INTO shipments (order_id, courier, tracking_number, status)
SELECT o.id, 'GHN', 'GHN-TRACK-2026001', 'PENDING'
FROM orders o JOIN users u ON u.id = o.user_id
WHERE u.email = 'customer1@example.com' AND o.total_amount = 840000 AND o.vat_amount = 67200
  AND o.shipping_fee = 30000 AND o.final_amount = 937200 AND o.payment_method = 'COD'
  AND o.shipping_address = '12 Le Loi, Hoan Kiem, Ha Noi'
ON CONFLICT (order_id) DO NOTHING;

INSERT INTO vouchers (code, discount_type, discount_value, min_order_value, max_discount, start_date, end_date, status)
VALUES
    ('WELCOME10', 'PERCENTAGE', 10, 300000, 100000, NOW(), NOW() + INTERVAL '30 days', 'ACTIVE'),
    ('FREESHIP', 'FIXED_AMOUNT', 30000, 0, 30000, NOW(), NOW() + INTERVAL '20 days', 'ACTIVE')
ON CONFLICT (code) DO NOTHING;

INSERT INTO voucher_products (voucher_id, product_id)
SELECT v.id, p.id
FROM vouchers v
JOIN products p ON p.slug = 'ao-thun-basic'
WHERE v.code = 'WELCOME10'
ON CONFLICT DO NOTHING;

INSERT INTO voucher_categories (voucher_id, category_id)
SELECT v.id, c.id
FROM vouchers v
JOIN categories c ON c.slug = 'ao-thun'
WHERE v.code = 'WELCOME10'
ON CONFLICT DO NOTHING;

INSERT INTO reviews (user_id, product_id, order_id, rating, title, comment, is_verified, status)
SELECT u.id, p.id, o.id, 5, 'San pham dep', 'Chat vai mem, form vua, rat dang tien.', TRUE, 'APPROVED'
FROM users u
JOIN products p ON p.slug = 'ao-thun-basic'
JOIN orders o ON o.user_id = u.id AND o.total_amount = 840000 AND o.vat_amount = 67200
    AND o.shipping_fee = 30000 AND o.final_amount = 937200 AND o.payment_method = 'COD'
    AND o.shipping_address = '12 Le Loi, Hoan Kiem, Ha Noi'
WHERE u.email = 'customer1@example.com'
  AND NOT EXISTS (SELECT 1 FROM reviews existing WHERE existing.user_id = u.id AND existing.product_id = p.id);

INSERT INTO review_images (review_id, image_url)
SELECT r.id, '/assets/products/seed-catalog/tshirts-white-basics-men-white-t-shirt-29787.jpg'
FROM reviews r
WHERE r.user_id = (SELECT id FROM users WHERE email = 'customer1@example.com')
  AND r.product_id = (SELECT id FROM products WHERE slug = 'ao-thun-basic')
  AND NOT EXISTS (SELECT 1 FROM review_images prior WHERE prior.review_id = r.id
                  AND prior.image_url = '/assets/products/seed-catalog/tshirts-white-basics-men-white-t-shirt-29787.jpg');

UPDATE review_images ri
SET image_url='/assets/products/seed-catalog/tshirts-white-basics-men-white-t-shirt-29787.jpg'
FROM reviews r
WHERE ri.review_id=r.id
  AND r.user_id=(SELECT id FROM users WHERE email='customer1@example.com')
  AND r.product_id=(SELECT id FROM products WHERE slug='ao-thun-basic');

INSERT INTO loyalty_points (user_id, total_points, available_points, redeemed_points, tier)
VALUES
    ((SELECT id FROM users WHERE email = 'customer1@example.com'), 250, 180, 70, 'SILVER'),
    ((SELECT id FROM users WHERE email = 'customer2@example.com'), 90, 90, 0, 'BRONZE')
ON CONFLICT (user_id) DO NOTHING;

INSERT INTO loyalty_transactions (user_id, points_change, reason, reference_type, reference_id)
SELECT u.id, t.points_change, t.reason, t.reference_type,
       CASE WHEN t.reference_type = 'ORDER' THEN o.id ELSE NULL END
FROM users u
JOIN orders o ON o.user_id = u.id AND o.total_amount = 840000 AND o.vat_amount = 67200
    AND o.shipping_fee = 30000 AND o.final_amount = 937200 AND o.payment_method = 'COD'
    AND o.shipping_address = '12 Le Loi, Hoan Kiem, Ha Noi'
CROSS JOIN (VALUES (250, 'Mua hang', 'ORDER'), (-70, 'Doi diem', 'VOUCHER')) AS t(points_change, reason, reference_type)
WHERE u.email = 'customer1@example.com'
  AND NOT EXISTS (
      SELECT 1 FROM loyalty_transactions existing
      WHERE existing.user_id = u.id AND existing.points_change = t.points_change
        AND existing.reason = t.reason AND existing.reference_type = t.reference_type
        AND ((t.reference_type = 'ORDER' AND existing.reference_id = o.id)
             OR (t.reference_type = 'VOUCHER' AND existing.reference_id IS NULL))
  );

COMMIT;

